def collect_parameters(uri_query='', body=None, headers=None,
    exclude_oauth_signature=True, with_realm=False):
    params = []

    if headers:
        auth_header = None
        for k, v in headers.items():
            if k.lower() == 'authorization':
                auth_header = v
                break

        if auth_header and auth_header.startswith('OAuth '):
            auth_params = utils.parse_authorization_header(auth_header)
            for k, v in auth_params:
                if exclude_oauth_signature and k == 'oauth_signature':
                    continue
                if not with_realm and k == 'realm':
                    continue
                params.append((k, v))

    if uri_query:
        params.extend(urldecode(uri_query))

    if body:
        decoded = extract_params(body)
        if decoded:
            params.extend(decoded)

