                if exclude_oauth_signature and k == 'oauth_signature':
                    continue
                if not with_realm and k == 'realm':
                    continue
                params.append((k, v))

    if uri_query:
        try:
            params.extend(urldecode(uri_query))
        except Exception:
            pass

    if body:
        decoded = extract_params(body)
        if decoded:
            params.extend(decoded)

    return params
