def _sign_hmac(hash_algorithm_name: str, sig_base_str: str, client_secret:
    str, resource_owner_secret: str):
    key = utils.escape(client_secret or '') + '&' + utils.escape(resource_owner_secret or '')
    key = key.encode('ascii')
    msg = sig_base_str.encode('ascii')

    hash_map = {
        'SHA-1': hashlib.sha1,
        'SHA-256': hashlib.sha256,
        'SHA-512': hashlib.sha512,
    }

    digestmod = hash_map[hash_algorithm_name]
    signature = hmac.new(key, msg, digestmod)
    return binascii.b2a_base64(signature.digest())[:-1].decode('ascii')
